// 取消是本人明确决定；归还/报酬规则尚未配置，本叶不生成钱粮或关系变化。
#include "envoy_task_cancellation.hpp"
#include "resident/domains/interaction/face_to_face_contact.hpp"
#include <algorithm>
namespace hanmo::resident {
bool envoy_cancellation_busy_allowed(const CommonStore& common,const TaskState& tasks,const EnvoyTaskState& envoy,const StableId& actor_id){
    const auto* actor=common.actor(actor_id);if((envoy.version!=1&&envoy.version!=2)||!actor||!actor->alive||!actor->available||actor->action_id.empty())return false;const auto* action=common.action(actor->action_id);if(!action||action->actor_id!=actor_id||action->remaining_ticks<1||(action->kind!="envoy_deliver"&&action->kind!="envoy_report"))return false;
    const EnvoyTaskContract* found=nullptr;for(const auto& row:envoy.envoy_contracts.rows())if(row.second.action&&row.second.action->action_id==action->id){if(found)return false;const auto& g=row.second;const auto* task=tasks.tasks.find(row.first);const bool report=g.action->kind==EnvoyTaskActionKind::report;const auto* provider=common.actor(g.action->context.provider_actor_id);if(!task||g.acceptance.task_id!=row.first||task->assignee!=actor_id||g.acceptance.envoy_actor_id!=actor_id||g.completion||(report?task->status!="ready":task->status!="active")||action->kind!=(report?"envoy_report":"envoy_deliver")||(!report&&g.action->kind!=EnvoyTaskActionKind::deliver)||!provider||provider->id==actor_id||provider->action_id!=action->id||action->participants.size()!=2||std::count(action->participants.begin(),action->participants.end(),actor_id)!=1||std::count(action->participants.begin(),action->participants.end(),provider->id)!=1)return false;found=&g;}
    return found!=nullptr;
}

Outcome<EnvoyTaskSource> preview_envoy_cancellation(const CommonStore& common,const TaskState& tasks,const EnvoyTaskState& envoy,const DiplomaticMissionRead& missions,const DiplomacyPresentationRead& presentations,const StableId& actor_id,const StableId& id,Integer revision){
    if(revision!=common.revision())return {false,{},common_failure("StaleWorldRevision").error};const auto* task=tasks.tasks.find(id);if(!task||task->assignee!=actor_id)return {false,{},common_failure("TaskNotKnown").error};if(task->status!="active"&&task->status!="ready")return {false,{},common_failure("TaskNotActive",id).error};EnvoyTaskRead read(common,tasks,envoy,missions,presentations);auto source=read.envoy_task_source(id);if(!source.ok)return source;if(source.value.completion)return {false,{},common_failure("TaskNotActive",id).error};const auto& a=source.value.acceptance;const auto* contract=envoy.envoy_contracts.find(id);const auto* actor=common.actor(actor_id);
    if(!actor||!actor->alive||!actor->available||actor->hp<=0)return {false,{},common_failure("ActorUnavailable",actor_id).error};if(!actor->action_id.empty()&&(!contract->action||actor->action_id!=contract->action->action_id))return {false,{},common_failure("ActorBusy",actor_id).error};
    if(source.value.delivery){if(source.value.delivery->completed_tick>common.tick())return {false,{},common_failure("EnvoyCancellationBeforeClock",id,ErrorKind::internal).error};}else if(common.tick()>=a.delivery_expires_tick)return {false,{},common_failure("EnvoyDeliveryExpired",id).error};
    if(contract->action){const auto& link=*contract->action;const auto* action=common.action(link.action_id);const auto* provider=common.actor(link.context.provider_actor_id);auto original=missions.diplomatic_mission_source(a.mission_authority_fact_id);if(!original.ok)return {false,{},original.error};const bool report=link.kind==EnvoyTaskActionKind::report;const auto work=report?original.value.report_work_ticks:original.value.delivery_work_ticks;
        if((link.kind!=EnvoyTaskActionKind::deliver&&!report)||!face_to_face_contact_context_valid(link.context)||link.context.place_id!=(report?a.report_site_id:a.delivery_site_id)||!action||action->kind!=(report?"envoy_report":"envoy_deliver")||action->actor_id!=actor_id||action->start_tick<a.accepted_tick||action->start_tick>common.tick()||action->remaining_ticks<1||action->remaining_ticks>work||common.tick()-action->start_tick<work-action->remaining_ticks||actor->action_id!=action->id||!provider||provider->id==actor_id||provider->action_id!=action->id||action->participants.size()!=2||std::count(action->participants.begin(),action->participants.end(),actor_id)!=1||std::count(action->participants.begin(),action->participants.end(),provider->id)!=1||(report?!source.value.delivery:bool(source.value.delivery)))return {false,{},common_failure("InvalidEnvoyCancellationAction",id,ErrorKind::internal).error};
    }
    return source;
}
Outcome<EnvoyTaskCompletion> cancel_envoy_task_in_candidate(CommonStore& common,TaskState& tasks,EnvoyTaskState& envoy,const DiplomaticMissionRead& missions,const DiplomacyPresentationRead& presentations,const StableId& actor_id,const StableId& id,Integer revision,const EnvoyReleaseAction& release){
    if(revision!=common.revision())return {false,{},common_failure("StaleWorldRevision").error};const auto* original_task=tasks.tasks.find(id);if(!original_task||original_task->assignee!=actor_id)return {false,{},common_failure("TaskNotKnown").error};if(original_task->status!="active"&&original_task->status!="ready"&&original_task->status!="cancelled")return {false,{},common_failure("TaskNotActive",id).error};EnvoyTaskRead read(common,tasks,envoy,missions,presentations);auto old=read.envoy_task_source(id);if(!old.ok)return {false,{},old.error};if(old.value.completion&&old.value.completion->result==EnvoyTaskResult::cancelled)return {true,*old.value.completion,{}};
    auto source=preview_envoy_cancellation(common,tasks,envoy,missions,presentations,actor_id,id,revision);if(!source.ok)return {false,{},source.error};const auto& a=source.value.acceptance;auto* contract=envoy.envoy_contracts.find(id);
    if(contract->action){if(!release)return {false,{},common_failure("MissingEnvoyReleaseService",id,ErrorKind::internal).error};const auto link=*contract->action;const auto action=*common.action(link.action_id);auto original=missions.diplomatic_mission_source(a.mission_authority_fact_id);if(!original.ok)return {false,{},original.error};const auto work=link.kind==EnvoyTaskActionKind::report?original.value.report_work_ticks:original.value.delivery_work_ticks;
        auto released=release(link.action_id);if(!released.ok)return {false,{},released.error};if(common.action(link.action_id))return {false,{},common_failure("EnvoyActionNotReleased",link.action_id,ErrorKind::internal).error};for(const auto& person:action.participants){const auto* current=common.actor(person);if(current&&current->action_id==link.action_id)return {false,{},common_failure("EnvoyActionNotReleased",person,ErrorKind::internal).error};}
        auto fact=common.next_id("envoy_interruption");if(!fact.ok)return {false,{},fact.error};EnvoyHandoverInterruption interrupted;interrupted.fact_id=fact.value;interrupted.task_id=id;interrupted.contract_id=a.contract_id;interrupted.acceptance_fact_id=a.fact_id;interrupted.action_id=link.action_id;interrupted.action_kind=action.kind;interrupted.provider_actor_id=link.context.provider_actor_id;interrupted.place_id=link.context.place_id;interrupted.reason="CancelledByAssignee";interrupted.started_tick=action.start_tick;interrupted.stopped_tick=common.tick();interrupted.completed_work_ticks=work-action.remaining_ticks;auto wrote=common.append_fact({fact.value,"envoy_handover_interrupted","tasks"});if(!wrote.ok)return {false,{},wrote.error};contract->interruptions.push_back(std::move(interrupted));contract->action.reset();
    }
    auto fact=common.next_id("envoy_cancel");if(!fact.ok)return {false,{},fact.error};EnvoyTaskCompletion final;final.fact_id=fact.value;final.task_id=id;final.contract_id=a.contract_id;final.acceptance_fact_id=a.fact_id;if(source.value.delivery)final.delivery_fact_id=source.value.delivery->fact_id;final.result=EnvoyTaskResult::cancelled;final.completed_tick=common.tick();final.reason="CancelledByAssignee";auto wrote=common.append_fact({final.fact_id,"envoy_task_cancelled","tasks"});if(!wrote.ok)return {false,{},wrote.error};contract->completion=final;contract->pending_code.clear();auto* task=tasks.tasks.find(id);task->status="cancelled";task->settlement_id=final.fact_id;task->reported_tick=common.tick();return {true,std::move(final),{}};
}
}
